def book_reservation(user_id: str, origin: str, destination: str, flight_type: str, cabin: str, flights: list, passengers: list, payment_methods: list, total_baggages: int, nonfree_baggages: int, insurance: str):
    """
    Book a reservation.

    SLOT-FILLING FORMATS (fill each argument EXACTLY like this; this tool auto-corrects a
    few common mistakes, but follow the formats to avoid errors):
    - flights: a list of objects, one per leg, each EXACTLY {"flight_number": "HAT271", "date": "2024-05-26"}.
      Do NOT add origin/destination/price/time keys.
    - passengers: a list of objects, one per passenger, each EXACTLY
      {"first_name": "Sophia", "last_name": "Silva", "dob": "1957-10-05"}.
      Use the key "dob" in YYYY-MM-DD format (NOT "date_of_birth"). Do not add seat preferences.
    - payment_methods: a list of objects, each EXACTLY {"payment_id": "certificate_8045380", "amount": 348}.
      Use the payment id string exactly as it appears in the user profile, and "amount" is the
      dollars charged to that method. The amounts across ALL methods MUST add up to the
      reservation total. If you are unsure how to split the total across several cards, just
      pass each method with its "amount" left out (or wrong) and this tool will compute a valid
      split for you (gift cards / certificates used first up to their balance, remainder on the
      credit card).
    - insurance: exactly the string "yes" or "no".

    Args:
        user_id: The ID of the user to book the reservation such as 'sara_doe_496'.
        origin: The IATA code for the origin city such as 'SFO'.
        destination: The IATA code for the destination city such as 'JFK'.
        flight_type: The type of flight, exactly 'one_way' or 'round_trip'.
        cabin: The cabin class, exactly 'basic_economy', 'economy', or 'business'.
        flights: An array of {"flight_number","date"} objects, one per leg.
        passengers: An array of {"first_name","last_name","dob"} objects.
        payment_methods: An array of {"payment_id","amount"} objects; amounts must sum to the reservation total.
        total_baggages: The total number of baggage items to book the reservation.
        nonfree_baggages: The number of non-free (paid) baggage items to book the reservation.
        insurance: Whether the reservation has insurance, exactly 'yes' or 'no'.
    """
    import re

    def _norm_passenger(p):
        if not isinstance(p, dict):
            return p
        q = dict(p)
        if "dob" not in q:
            for alt in ("date_of_birth", "birth_date", "dateOfBirth", "DOB", "birthday", "dateofbirth"):
                if alt in q:
                    q["dob"] = q.pop(alt)
                    break
        return {k: q[k] for k in ("first_name", "last_name", "dob") if k in q}

    def _norm_flight(f):
        if not isinstance(f, dict):
            return f
        q = dict(f)
        if "flight_number" not in q:
            for alt in ("flightNumber", "flight_no", "number", "flight"):
                if alt in q and isinstance(q[alt], str):
                    q["flight_number"] = q[alt]
                    break
        return {k: q[k] for k in ("flight_number", "date") if k in q}

    def _norm_payment(p):
        if not isinstance(p, dict):
            return p
        q = dict(p)
        if "payment_id" not in q:
            for alt in ("id", "payment_method_id", "paymentId", "payment_method", "source_id"):
                if alt in q and isinstance(q[alt], str):
                    q["payment_id"] = q[alt]
                    break
        out = {}
        if "payment_id" in q:
            out["payment_id"] = q["payment_id"]
        # "amount" is a REQUIRED field on the Payment model: if it is missing the booking
        # raises a validation error before any recoverable check runs. Inject a 0 placeholder
        # so the reservation-total check fires instead, letting the auto-split below compute a
        # valid amount. A 0 placeholder is only ever used when the amount was absent/None, so a
        # payment that already carries a correct amount is untouched.
        if q.get("amount") is not None:
            out["amount"] = q["amount"]
        else:
            out["amount"] = 0
        return out

    def _norm_insurance(v):
        if v in (None, "none", "None", "no", "No", "NO", "false", "False", False, ""):
            return "no"
        if v in ("yes", "Yes", "YES", "true", "True", True):
            return "yes"
        return v

    if isinstance(passengers, list):
        passengers = [_norm_passenger(p) for p in passengers]
    if isinstance(flights, list):
        flights = [_norm_flight(f) for f in flights]
    if isinstance(payment_methods, list):
        payment_methods = [_norm_payment(p) for p in payment_methods]
    insurance = _norm_insurance(insurance)

    def _call(pms):
        return env_book_reservation(
            user_id=user_id, origin=origin, destination=destination,
            flight_type=flight_type, cabin=cabin, flights=flights,
            passengers=passengers, payment_methods=pms,
            total_baggages=total_baggages, nonfree_baggages=nonfree_baggages,
            insurance=insurance,
        )

    result = _call(payment_methods)

    # If the booking failed ONLY because the payment amounts do not sum to the reservation
    # total, compute a valid split deterministically and retry once. This fires only on the
    # exact "Payment amount does not add up" failure (no reservation is persisted on that
    # failure), so a booking whose amounts are already correct is never touched.
    if isinstance(result, str) and "total price is" in result and isinstance(payment_methods, list) and payment_methods:
        m = re.search(r"total price is (\d+)", result)
        if m:
            total = int(m.group(1))
            user = env_get_user_details(user_id=user_id)
            if isinstance(user, dict):
                profile = user.get("payment_methods", {}) or {}

                def _source(pid):
                    return (profile.get(pid) or {}).get("source", "")

                def _balance(pid):
                    bal = (profile.get(pid) or {}).get("amount")
                    try:
                        return int(bal)
                    except (TypeError, ValueError):
                        return None

                ids = [p.get("payment_id") for p in payment_methods if isinstance(p, dict)]
                # Every provided method must exist on the profile before we auto-split.
                if ids and all(pid in profile for pid in ids):
                    rank = {"certificate": 0, "gift_card": 1}
                    ordered = sorted(payment_methods, key=«redacted» p: rank.get(_source(p["payment_id"]), 2))
                    remaining = total
                    assigned = {}
                    for p in ordered:
                        pid = p["payment_id"]
                        src = _source(pid)
                        if src in ("certificate", "gift_card"):
                            bal = _balance(pid)
                            amt = remaining if bal is None else min(bal, remaining)
                        else:  # credit card absorbs the remainder
                            amt = remaining
                        amt = max(0, min(amt, remaining))
                        assigned[pid] = amt
                        remaining -= amt
                    if remaining == 0:
                        filled = [{"payment_id": p["payment_id"], "amount": assigned[p["payment_id"]]} for p in payment_methods]
                        return _call(filled)
    return result
